namespace {
std::string context;
void check(bool ok,const std::string& why){if(!ok)throw std::runtime_error(context+": "+why);}
std::vector<Pixel> words(const JsonArray& a){std::vector<Pixel> result;for(auto v:a)result.push_back(Pixel(v.GetNumber()));return result;}
void pixels(const timeline::Surface& actual,const JsonArray& expected){const auto wanted=words(expected);if(actual.pixels==wanted)return;for(std::size_t i=0;i<std::min(actual.pixels.size(),wanted.size());++i)if(actual.pixels[i]!=wanted[i])check(false,"pixel "+std::to_string(i)+" got "+std::to_string(actual.pixels[i])+" wanted "+std::to_string(wanted[i]));check(false,"pixel length");}
void state(const Document& d,const JsonObject& expected){const auto* s=d.activeSurfaceIfPresent();check(bool(s),"missing surface");check(s->width==int(expected.GetNamedNumber(L"width"))&&s->height==int(expected.GetNamedNumber(L"height"))&&s->offsetX==int(expected.GetNamedNumber(L"ox"))&&s->offsetY==int(expected.GetNamedNumber(L"oy"))&&s->storageOriginX==int(expected.GetNamedNumber(L"sx"))&&s->storageOriginY==int(expected.GetNamedNumber(L"sy")),"geometry/origin");pixels(*s,expected.GetNamedArray(L"pixels"));}
void sameSurface(const timeline::Surface& a,const timeline::Surface& b){check(a.format==b.format&&a.width==b.width&&a.height==b.height&&a.offsetX==b.offsetX&&a.offsetY==b.offsetY&&a.storageOriginX==b.storageOriginX&&a.storageOriginY==b.storageOriginY&&a.pixels==b.pixels,"original surface changed");}
void encoded(const Document& d){if(d.colorMode()!=color_mode::Mode::Indexed)return;bool duplicates=false;std::unordered_set<int> ids;for(const auto& e:d.palette().entries)duplicates|=!ids.insert(e.id).second;
 for(int k=0;k<3;++k){try{auto out=k==0?project::encodeEditableProject(d):k==1?project::encodeRecoveryProject(d):project::encodeHistoryProject(d);check(!duplicates,"encoder accepted duplicates");auto manifest=project::readProjectManifest(out.bytes);project::Archive zip(out.bytes);check(manifest.colorMode=="indexed","encoded mode");for(const auto& c:manifest.cels)if(c.surface){const auto* runtime=d.timeline().resolveSurface(c.id).surface;const auto& s=*c.surface;check(runtime&&s.format==project::RasterFormat::Indexed&&project::decodeRaster(zip.read(s.dataFile,project::Limits{}.expandedBytes),s.dataEncoding,s.format,s.width,s.height,project::Limits{}.expandedBytes)==runtime->pixels,"encoded raw IDs");}bool gated=false;try{project::prepareEditableImport(manifest);}catch(const project::Error& e){gated=e.kind==project::ErrorKind::Unsupported;}check(gated,"indexed production admission");}catch(const project::Error& e){check(duplicates&&e.kind==project::ErrorKind::Corrupt,std::string("encoder error: ")+e.what());}}
}
liquify::Options options(const JsonObject& row){return {liquify::Mode(int(row.GetNamedNumber(L"mode"))),int(row.GetNamedNumber(L"radius")),int(row.GetNamedNumber(L"strength")),row.GetNamedBoolean(L"smoothing"),int(row.GetNamedNumber(L"smoothingStrength"))};}
void gesture(Document& d,const JsonObject& row){auto p=row.GetNamedObject(L"start");check(d.beginLiquify({p.GetNamedNumber(L"x"),p.GetNamedNumber(L"y")},options(row)),"begin");for(auto v:row.GetNamedArray(L"ops")){auto op=v.GetArray();if(op.GetStringAt(0)==L"hold")d.holdLiquify();else d.updateLiquify({op.GetNumberAt(1),op.GetNumberAt(2)});}}
}
namespace moon {struct RasterHistoryFixture {
 static std::unique_ptr<Document> make(const JsonObject& row,int linkKind=0){auto d=std::make_unique<Document>(int(row.GetNamedNumber(L"w")),int(row.GetNamedNumber(L"h")));auto t=d->timeline_.state();auto& s=*t.cels.front().surface;s.format=row.GetNamedString(L"format")==L"indexed"?timeline::RasterFormat::Indexed:timeline::RasterFormat::Rgba;s.width=int(row.GetNamedNumber(L"sw"));s.height=int(row.GetNamedNumber(L"sh"));s.offsetX=int(row.GetNamedNumber(L"ox"));s.offsetY=int(row.GetNamedNumber(L"oy"));s.storageOriginX=5;s.storageOriginY=-3;s.pixels=words(row.GetNamedArray(L"initial"));
  if(linkKind){auto source=t.cels.front();for(int i=1;i<=2;++i){auto frame=t.frames.front();frame.id="liquify-frame-"+std::to_string(i);t.frames.push_back(frame);auto alias=source;alias.id="liquify-alias-"+std::to_string(i);alias.frameId=frame.id;alias.surface.reset();alias.linkedCelId=i==1?source.id:"liquify-alias-1";t.cels.push_back(alias);}if(linkKind==1)d->activeFrameId_=t.frames.back().id;}
  if(row.GetNamedValue(L"mask").ValueType()==JsonValueType::Object){const auto m=row.GetNamedObject(L"mask");timeline::MaskSlot slot;slot.ownerId=t.layers.front().id;slot.frameId=d->activeFrameId_;slot.mask.id="liquify-mask";slot.mask.surface.width=int(m.GetNamedNumber(L"width"));slot.mask.surface.height=int(m.GetNamedNumber(L"height"));slot.mask.surface.pixels=words(m.GetNamedArray(L"pixels"));t.masks.push_back(std::move(slot));}
  d->timeline_=timeline::Timeline(std::move(t));d->colorMode_=row.GetNamedString(L"format")==L"indexed"?color_mode::Mode::Indexed:color_mode::Mode::Rgba;auto& p=d->palette_;p.entries.clear();p.slots.clear();for(auto v:row.GetNamedArray(L"entries")){auto e=v.GetObject();p.entries.push_back({int(e.GetNamedNumber(L"id")),U"color",Pixel(e.GetNamedNumber(L"color"))});}std::vector<int> order;for(auto id:words(row.GetNamedArray(L"order")))order.push_back(int(id));p.setOrder(std::move(order));p.nextId=100;
  if(row.GetNamedValue(L"selection").ValueType()==JsonValueType::Object){auto v=row.GetNamedObject(L"selection");SelectionMask sel{int(v.GetNamedNumber(L"x")),int(v.GetNamedNumber(L"y")),int(v.GetNamedNumber(L"width")),int(v.GetNamedNumber(L"height")),{}};for(auto b:words(v.GetNamedArray(L"mask")))sel.mask.push_back(std::uint8_t(b));d->previewSelection(sel);}d->projectActiveCelOpacities();d->markSaved();return d;
 }
 static void links(const Document& d,const timeline::State& before){const timeline::Timeline previous(before);for(const auto& c:before.cels){const auto* now=d.timeline_.findCelById(c.id);check(now&&now->linkedCelId==c.linkedCelId&&now->runtimeSharedCelId==c.runtimeSharedCelId,"links not restored for "+c.id+" got "+(now?now->linkedCelId.value_or("none"):"missing")+" wanted "+c.linkedCelId.value_or("none"));const auto expected=previous.resolveSurface(c.id);const auto actual=d.timeline_.resolveSurface(c.id);check(expected.surface&&actual.surface,"link owner missing");sameSurface(*expected.surface,*actual.surface);}}
 static void run(const JsonObject& row,int linkKind=0){auto d=make(row,linkKind);const auto before=*d->activeSurfaceIfPresent();const auto beforeTimeline=d->timeline_.state();const auto active=d->cel().id;const auto pal=d->palette_;const auto sel=d->selection();const bool expanded=row.GetNamedBoolean(L"expanded"),changed=row.GetNamedBoolean(L"changed");gesture(*d,row);state(*d,row.GetNamedObject(L"preview"));check(d->commitLiquify()==changed,"commit result");check(d->historySize()==(changed?1:0)&&!d->active()&&d->dirty()==changed,"single history/no-op");check(indexed_adjustment::samePaletteData(pal,d->palette_)&&selectionEqual(sel,d->selection()),"palette/selection changed");
  if(changed){state(*d,row.GetNamedObject(L"after"));const auto& history=d->history_.latest();check(history.label==U"\u6db2\u5316"&&bool(history.children.back().contentHistory.dense)==row.GetNamedBoolean(L"dense"),"history label/dense threshold");if(row.GetNamedValue(L"replayOrder").ValueType()==JsonValueType::Array){std::vector<int> order;for(auto id:words(row.GetNamedArray(L"replayOrder")))order.push_back(int(id));d->palette_.setOrder(std::move(order));}const auto current=d->palette_;
   if(linkKind)encoded(*d);d->undo();if(linkKind)links(*d,beforeTimeline);else if(expanded)sameSurface(d->activeSurface(),before);else state(*d,row.GetNamedObject(L"undo"));check(d->cel().id==active&&indexed_adjustment::samePaletteData(current,d->palette_),"undo active/palette");if(linkKind)encoded(*d);d->redo();state(*d,row.GetNamedObject(L"redo"));check(d->cel().id==active&&indexed_adjustment::samePaletteData(current,d->palette_),"redo active/palette");if(linkKind)encoded(*d);
   if(linkKind){const timeline::Timeline previous(beforeTimeline);for(const auto& c:beforeTimeline.cels)if(c.id!=active){const auto* now=d->timeline_.resolveSurface(c.id).surface;const auto* was=previous.resolveSurface(c.id).surface;check(now&&was,"peer missing");sameSurface(*now,*was);}}
  }
  auto cancelled=make(row,linkKind);const auto cancelTimeline=cancelled->timeline_.state();gesture(*cancelled,row);cancelled->cancelStroke();check(!cancelled->active()&&!cancelled->historySize()&&!cancelled->dirty(),"cancel history/dirty");if(linkKind)links(*cancelled,cancelTimeline);else if(expanded)sameSurface(cancelled->activeSurface(),before);else state(*cancelled,row.GetNamedObject(L"cancel"));
 }
 static void edges(const JsonObject& row){for(int kind=0;kind<5;++kind){auto d=make(row);auto t=d->timeline_.state();if(kind==0)t.layers.front().locked=true;if(kind==1)t.layers.front().visible=false;if(kind==2)t.layers.front().kind="text";if(kind==3)t.cels.clear();if(kind<4)d->timeline_=timeline::Timeline(std::move(t));else check(d->beginLiquify({5,5},{}),"active fixture");const auto revision=d->revision();check(!d->beginLiquify({5,5},{})&&!d->historySize()&&revision==d->revision(),"unavailable target changed");d->cancelStroke();}
  auto d=make(row);const auto before=d->activeSurface();check(!d->beginLiquify({std::numeric_limits<double>::infinity(),0},{})&&!d->beginLiquify({0,std::numeric_limits<double>::quiet_NaN()},{}),"nonfinite begin");check(d->beginLiquify({5,5},{}),"valid begin");check(!d->updateLiquify({std::numeric_limits<double>::quiet_NaN(),0}),"nonfinite move");check(!d->commitLiquify(),"empty commit");sameSurface(d->activeSurface(),before);check(!d->historySize()&&!d->dirty(),"invalid/empty transaction");
 }
};}
int run(int argc,wchar_t** argv){check(argc==2,"oracle path");std::ifstream in(std::filesystem::path(argv[1]),std::ios::binary);check(bool(in),"missing oracle");const std::string bytes{std::istreambuf_iterator<char>(in),{}};const auto rows=JsonObject::Parse(winrt::to_hstring(bytes)).GetNamedArray(L"cases");check(rows.Size()==3230,"oracle coverage");unsigned links=0,dense=0;for(unsigned i=0;i<rows.Size();++i){const auto row=rows.GetObjectAt(i);context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::run(row);if(row.GetNamedBoolean(L"dense"))++dense;if(!row.GetNamedBoolean(L"expanded")&&(i%53==0||row.GetNamedBoolean(L"dense"))){for(int kind:{1,2}){RasterHistoryFixture::run(row,kind);++links;}}}context="edges";RasterHistoryFixture::edges(rows.GetObjectAt(0));std::cout<<rows.Size()<<" actual legacy indexed/RGBA liquify cases, "<<dense<<" dense histories and "<<links<<" linked/codec variants passed\n";return 0;}
int wmain(int argc,wchar_t** argv){const auto hr=RoInitialize(RO_INIT_MULTITHREADED);try{const auto result=run(argc,argv);if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return result;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return 1;}}
